    """On a main/anti-diagonal line, each same-color run extends away from foreign on-line cells to the border."""
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    bgc=Counter(v for r in g for v in r).most_common(1)[0][0]
    for ori in ('D','A'):
