    for ori,(dr,dc) in step.items():
        d=defaultdict(list)
        for i in range(h):
            for j in range(w):
                if g[i][j]!=bgc: d[key[ori](i,j)].append((i,j,g[i][j]))
        for k in d: d[k].sort()
        for k,cl in d.items():
            runs=[];cur=[cl[0]]
            for c in cl[1:]:
